import {api,clearSession} from './storage.js';
import {resolveAnswer,score} from './core.js';
import {loadModels,capture} from './face.js';
import {contextImage} from './visuals.js';
function photo(category,extra=''){const image=contextImage(category);return `<figure class="context-photo ${extra}"><img src="./images/${image.file}.jpg" alt="${image.alt}" width="1400" height="934" decoding="async"><figcaption>${image.label} <span>Topic inspiration · not a location clue</span></figcaption></figure>`;}
const $=s=>document.querySelector(s),main=$('main');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;
let user=null,view='auth',busy=false,generation=0,stream=null,cameraReady=false,recognition=null,advanceTimer=null,toastTimer=null,speechRetryTimer=null,speechRetries=0;
let speechLanguage='en-US';try{const stored=localStorage.getItem('geovoice-speech-language');if(['en-US','en-PH','en-GB'].includes(stored))speechLanguage=stored;}catch{}
let run=null,answerLocked=false,autoListen=false,routeVersion=0,config={categories:[],registrationOpen:true},draft=null;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6000);}
function stopCamera(){generation++;stream?.getTracks().forEach(t=>t.stop());stream=null;cameraReady=false;}
function stopSpeech(){clearTimeout(speechRetryTimer);if(recognition){recognition.onend=null;recognition.onresult=null;recognition.onerror=null;try{recognition.abort();}catch{}recognition=null;}$('#listen')?.classList.remove('listening');if($('#listen'))$('#listen').disabled=false;}
function cleanup(){stopCamera();stopSpeech();clearTimeout(advanceTimer);window.speechSynthesis?.cancel();busy=false;}
function shell(section,sub){window.requestAnimationFrame?.(()=>window.scrollTo?.({top:0,behavior:'instant'}));document.body.dataset.view=view;const focused=view==='camera'||view==='quiz';document.body.classList.toggle('focus-mode',focused);for(const selector of ['.sidebar','.topbar','footer'])$(selector).hidden=focused;$('#breadcrumb').innerHTML=`${esc(section)} <span class="muted">/ ${esc(sub)}</span>`;$('#account').textContent=user?user.name.slice(0,1).toUpperCase():'?';$('#account').title=user?user.name:'Sign in';const active={'Geography quiz':'quiz','My progress':'history','My profile':'settings'}[section];document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===active));}
function intro(kicker,title,subtitle){return `<section class="intro"><span class="eyebrow">${kicker}</span><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></section>`;}
function errorMessage(error){toast(error.message);}
function passwordInput(id,label='Password',autocomplete='current-password'){return `<label for="${id}">${label}</label><input id="${id}" type="password" minlength="15" maxlength="128" required autocomplete="${autocomplete}">`;}
function auth(mode='login'){
 cleanup();draft=null;routeVersion++;view='auth';shell('Geography quiz','Sign in');
 const register=mode==='register',recover=mode==='recover';
 main.innerHTML=intro('EXPLORE WITH GEOVOICE',recover?'Recover your account.':register?'Your next discovery starts here.':'Welcome back.','A whole world of discoveries. One curious you.')+`<div class="grid"><section class="card"><div class="form-tabs"><button id="login-tab" class="${mode==='login'?'selected':''}">Sign in</button><button id="register-tab" class="${register?'selected':''}" ${!config.registrationOpen?'disabled':''}>Create account</button></div><h2>${recover?'Use your recovery code':register?'Create your account':'Sign in to GeoVoice'}</h2><form id="auth-form">${register?'<label for="name">Your name</label><input id="name" type="text" required maxlength="60" autocomplete="name">':''}<label for="username">Username</label><input id="username" type="text" required pattern="[A-Za-z0-9_]{3,32}" minlength="3" maxlength="32" autocomplete="username" autocapitalize="none" spellcheck="false">${recover?'<label for="recovery">Recovery code</label><input id="recovery" type="text" required maxlength="100" autocomplete="off" spellcheck="false">':''}${passwordInput('password',recover?'New password':'Password',register||recover?'new-password':'current-password')}${register||recover?'<p class="fine">Use 15–128 characters. A long, unique passphrase works well.</p>'+passwordInput('confirm-password','Confirm password','new-password'):''}${register?'<label class="check"><input type="checkbox" id="consent" required>I agree to store my face template for sign-in.</label><button class="text-button" type="button" id="privacy-form">Read the privacy notice</button>':''}${recover?'<p class="fine">Your recovery code replaces your sign-in checks. Keep it private. A successful reset replaces this code.</p>':''}<div id="form-error" class="notice error" role="alert" hidden></div><button class="button primary full" id="auth-submit">${register?'Continue to face enrollment':recover?'Reset password':'Continue to face verification'} →</button></form>${!register&&!recover?'<button id="recover-link" class="text-button full">Recover account or reset password</button>':''}</section><section class="card camera-card explorer-card"><div class="travel-stamp" aria-hidden="true">✦ EXPLORER PASS</div><div class="globe-art" aria-hidden="true"><span>✦</span><i></i><b>↗</b></div><span class="eyebrow" style="color:var(--mint)">YOUR NEXT ADVENTURE</span><h2 class="spaced">Big world.<br>Bigger curiosity.</h2><p style="color:#b7d1dc">Sign in with your username and password, then verify your face.</p><div class="status-line spaced"><span class="number">1</span><span>Username & password</span></div><div class="status-line spaced"><span class="number">2</span><span>Face verification</span></div><p class="fine" style="color:#b7d1dc;margin-top:30px">The same face can be used with different usernames. Each account has its own progress.</p></section></div>`;
 $('#login-tab').onclick=()=>{if(!busy)auth();};$('#register-tab').onclick=()=>{if(!busy)auth('register');};$('#recover-link')?.addEventListener('click',()=>{if(!busy)auth('recover');});$('#privacy-form')?.addEventListener('click',privacy);
 $('#auth-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const password=$('#password').value;if((register||recover)&&password!==$('#confirm-password').value){$('#form-error').hidden=false;$('#form-error').textContent='The passwords do not match.';return;}busy=true;$('#auth-submit').disabled=true;$('#form-error').hidden=true;
  try{if(register){draft={name:$('#name').value.trim(),username:$('#username').value.trim(),password,consent:$('#consent').checked,consentVersion:config.consentVersion};camera('register');}
   else{const response=await api(recover?'/auth/recover':'/auth/login','POST',recover?{username:$('#username').value.trim(),recoveryCode:$('#recovery').value,newPassword:password}:{username:$('#username').value.trim(),password});if(response.stage==='face')camera('login');else {user=response.user;showIdentitySuccess(response.recoveryCode);}}
  }catch(error){if($('#form-error')){$('#form-error').hidden=false;$('#form-error').textContent=error.message;}}finally{busy=false;if($('#auth-submit'))$('#auth-submit').disabled=false;}
 };
}
function cameraMessage(message,error=false){const el=$('#camera-message');if(el){el.textContent=message;el.style.color=error?'#ffb49c':'';}}
async function listCameras(selected){if(!navigator.mediaDevices?.enumerateDevices)return;try{const devices=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='videoinput');const select=$('#camera-select');if(!select)return;select.innerHTML='<option value="">Default camera</option>'+devices.filter(d=>d.deviceId).map((d,i)=>`<option value="${esc(d.deviceId)}">${esc(d.label||`Camera ${i+1}`)}</option>`).join('');if(devices.some(d=>d.deviceId===selected))select.value=selected;}catch{cameraMessage('Camera names are available after you grant permission.');}}
function camera(mode){cleanup();view='camera';routeVersion++;shell('Geography quiz',mode==='register'?'Face enrollment':'Face verification');
 main.innerHTML='<button id="camera-exit" class="button secondary focus-back">← Back</button>'+intro('FACE VERIFICATION',mode==='register'?'Let’s set up your face.':'Look at the camera.','Choose your webcam, use good lighting, and keep only one person in view.')+`<div class="grid"><section class="card camera-card"><div class="camera-head"><span>Camera preview</span><span class="pill" id="camera-status">Camera off</span></div><div class="camera-stage"><video id="video" autoplay muted playsinline aria-label="Live camera preview"></video><div class="camera-outline"></div></div><p id="camera-message" class="camera-message" role="status">Choose a camera and enable it when you’re ready.</p></section><section class="card"><h2>${mode==='reenroll'?'Update your face template':mode==='register'?'Enroll your face':'Verify your face'}</h2><label for="camera-select">Webcam</label><select id="camera-select"><option value="">Default camera</option></select><button class="button secondary full" id="camera-enable">Enable camera</button><button class="button primary full" id="capture" disabled>${mode==='login'?'Verify my face':'Capture my face'} →</button><button class="text-button full" id="camera-stop">Turn camera off</button><button class="text-button full" id="camera-back">${mode==='reenroll'?'Back to my profile':'Back to sign in'}</button><p class="fine">Camera images are processed on your device and are not uploaded. A numerical face template is sent securely for verification.</p></section></div>`;
 let preferred='';try{preferred=localStorage.getItem('geovoice-camera')||'';}catch{}void listCameras(preferred);
 const setBusy=value=>{busy=value;for(const id of ['camera-enable','capture','camera-select','camera-back','camera-exit'])if($('#'+id))$('#'+id).disabled=value||(id==='capture'&&!cameraReady);};
 const enable=async()=>{if(busy)return;const device=$('#camera-select').value;stopCamera();const ticket=generation;setBusy(true);cameraMessage('Allow camera access when your browser asks.');try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera access needs HTTPS or localhost and a supported browser.');const next=await navigator.mediaDevices.getUserMedia({video:device?{deviceId:{exact:device},width:{ideal:640},height:{ideal:480}}:{width:{ideal:640},height:{ideal:480},facingMode:'user'},audio:false});if(ticket!==generation){next.getTracks().forEach(t=>t.stop());return;}stream=next;$('#video').srcObject=stream;await $('#video').play();cameraMessage('Preparing face recognition…');await loadModels();if(ticket!==generation)return;cameraReady=true;$('#camera-status').textContent='Camera on';const actual=stream.getVideoTracks()[0]?.getSettings().deviceId||device;try{localStorage.setItem('geovoice-camera',actual);}catch{}await listCameras(actual);cameraMessage('Ready. Look at the camera, then capture your face.');}catch(error){if(ticket!==generation)return;stopCamera();const messages={NotAllowedError:'Camera access was denied. Allow it in your browser settings and retry.',NotFoundError:'No webcam was found. Connect your camera and try again.',OverconstrainedError:'That camera is unavailable. Select a different camera.',NotReadableError:'Your camera is in use or unavailable. Close other camera apps and retry.'};cameraMessage(messages[error.name]||error.message,true);}finally{if(view==='camera')setBusy(false);}};
 $('#camera-enable').onclick=enable;$('#camera-select').onchange=async()=>{if(stream)await enable();};$('#camera-stop').onclick=()=>{stopCamera();if($('#video'))$('#video').srcObject=null;$('#camera-status').textContent='Camera off';cameraMessage('Camera turned off.');setBusy(false);};$('#camera-back').onclick=async()=>{draft=null;if(mode==='reenroll')settings();else{try{await api('/auth/logout','POST',{});}catch{}clearSession();auth();}};
 $('#camera-exit').onclick=()=>{if(!busy)$('#camera-back').click();};main.focus({preventScroll:true});window.scrollTo?.({top:0,behavior:'instant'});
 $('#capture').onclick=async()=>{if(busy||!cameraReady)return;setBusy(true);const ticket=generation;try{const samples=await capture($('#video'),mode==='login'?2:3,cameraMessage,()=>ticket!==generation);if(ticket!==generation)return;$('#camera-stop').disabled=true;const response=await api(mode==='register'?'/auth/register':mode==='reenroll'?'/account/face':'/auth/face','POST',mode==='register'?{...draft,samples}:mode==='reenroll'?{password:draft.password,consent:true,samples}:{samples});draft=null;if(mode==='reenroll'){user=response.user;settings();toast('Your face template has been updated.');}else {user=response.user;showIdentitySuccess(response.recoveryCode);}}catch(error){if(view==='camera')cameraMessage(error.message,true);}finally{if(view==='camera'){setBusy(false);$('#camera-stop').disabled=false;}}};
}
function recoveryDialog(code){const dialog=document.createElement('dialog');dialog.setAttribute('aria-labelledby','recovery-title');dialog.innerHTML=`<h2 id="recovery-title">Save your recovery code</h2><p>You’ll need this code if you forget your password or cannot verify your face.</p><code class="recovery-code">${esc(code)}</code><p class="fine">Store it somewhere private. It is shown only once and can be used once.</p><label class="check"><input type="checkbox" id="saved-code">I have saved my recovery code.</label><button class="button primary full" id="recovery-done" disabled>Continue</button>`;document.body.append(dialog);$('#saved-code').onchange=()=>$('#recovery-done').disabled=!$('#saved-code').checked;$('#recovery-done').onclick=()=>{dialog.close();dialog.remove();main.focus();};dialog.oncancel=e=>e.preventDefault();dialog.showModal();}
function showIdentitySuccess(code){home();const dialog=document.createElement('dialog');dialog.className='identity-success';dialog.setAttribute('aria-labelledby','success-title');dialog.innerHTML=`<div class="identity-success-icon" aria-hidden="true">✓</div><span class="eyebrow">VERIFICATION COMPLETE</span><h2 id="success-title">Identity confirmed!</h2><p>Welcome, ${esc(user.name)}. Your sign-in checks are complete.</p><div class="notice">You are signed in. Your camera is now off.</div><button class="button primary full" id="identity-continue">${code?'Save recovery code':'Continue to quiz'} →</button>`;document.body.append(dialog);const close=()=>{dialog.close();dialog.remove();if(code)recoveryDialog(code);else main.focus();};$('#identity-continue').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};dialog.showModal();}
function home(){cleanup();routeVersion++;view='home';shell('Geography quiz','Choose your journey');
 main.innerHTML=intro('READY TO EXPLORE',`Hello, ${user.name}. Where to today?`,'Pick a topic, turn on your curiosity, and let your voice lead the way.')+`<div class="journey-banner"><div><span class="eyebrow">YOUR EXPLORER PASSPORT</span><h2>Small questions.<br>Great big adventures.</h2><p>Find your next “I didn’t know that!”</p></div><div class="globe-art" aria-hidden="true"><span>✦</span><i></i><b>↗</b></div><span class="banner-stamp">EXPLORE · SPEAK · DISCOVER</span></div><div class="topic-grid">${config.categories.map((c,i)=>`<button type="button" class="topic-tile" data-topic="${esc(c)}"><img src="./images/${contextImage(c).file}.jpg" alt="" loading="lazy"><span><small>EXPEDITION 0${i+1}</small><strong>${esc(c)}</strong><b aria-hidden="true">↗</b></span></button>`).join('')}</div><div class="grid"><section class="card"><span class="eyebrow">BUILD YOUR QUIZ</span><h2 class="spaced">One question. A new discovery.</h2><form id="quiz-form"><label for="category">Choose your topic</label><select id="category"><option value="All">Around the world · All topics</option>${config.categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select><label for="count">Number of questions</label><select id="count"><option value="5">5 questions · A quick discovery</option><option value="10" selected>10 questions · A little adventure</option></select><label class="check"><input type="checkbox" id="auto-voice" ${!Speech?'disabled':''}>Listen automatically after each question. You can pause the microphone at any time.</label><p class="fine">Speech recognition may send audio to your browser provider and may need internet access. GeoVoice does not save audio.</p><button class="button primary full">Start exploring <span>→</span></button></form></section><section class="card camera-card"><span class="eyebrow" style="color:var(--mint)">HOW TO PLAY</span><h2 class="spaced">You know more<br>than you think.</h2><p style="color:#b7d1dc">Say the answer out loud, or simply say “A”, “B”, “C”, or “D”.</p><div class="status-line spaced"><span class="number">1</span><span>Read or listen to the question</span></div><div class="status-line spaced"><span class="number">2</span><span>Speak, click, or type your answer</span></div><div class="status-line spaced"><span class="number">3</span><span>Discover the answer and keep going</span></div><p class="fine" style="color:#b7d1dc;margin-top:30px">${Speech?'Voice recognition is available in this browser.':'Voice recognition is unavailable here. You can still click or type answers, or try Chrome with microphone access.'}</p></section></div>`;
 document.querySelectorAll('[data-topic]').forEach(button=>button.onclick=()=>{$('#category').value=button.dataset.topic;document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$('#quiz-form').scrollIntoView?.({behavior:'smooth',block:'center'});$('#category').focus();});
 $('#quiz-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const button=$('#quiz-form button');button.disabled=true;try{autoListen=$('#auto-voice').checked;const next=await api('/quizzes','POST',{category:$('#category').value,count:Number($('#count').value)});run={id:next.id,category:next.category,questions:Array(next.total),answers:[]};run.questions[0]=next.question;renderQuestion();}catch(error){errorMessage(error);}finally{busy=false;if(button.isConnected)button.disabled=false;}};
}
function renderQuestion(){stopSpeech();window.speechSynthesis?.cancel();clearTimeout(advanceTimer);view='quiz';routeVersion++;answerLocked=false;speechRetries=0;shell('Geography quiz','In progress');const i=run.answers.length,q=run.questions[i];
 main.innerHTML=`<div class="quiz-header"><div><span class="eyebrow">${esc(q.category)}</span><h1>Let curiosity lead.</h1></div><button id="exit" class="button secondary">✕ Quit & go home</button></div><div class="row"><span class="muted">Question ${i+1} of ${run.questions.length}</span><strong>${score(run.answers).correct} correct</strong></div><div class="progress-track" role="progressbar" aria-label="Quiz progress" aria-valuemin="0" aria-valuemax="${run.questions.length}" aria-valuenow="${i}"><div class="progress-fill" style="width:${i/run.questions.length*100}%"></div></div><div class="quiz-layout"><section class="card"><div class="row"><span class="smallcaps muted">LET’S SEE WHAT YOU KNOW</span><button class="text-button" id="read">Read aloud ♫</button></div><div class="question-scene"><h2 class="question" tabindex="-1">${esc(q.prompt)}</h2>${photo(q.category)}</div><div class="answers">${q.options.map((o,j)=>`<button class="answer" data-answer="${j}"><span class="answer-shape" aria-hidden="true">${['▲','◆','●','■'][j]}</span><span class="answer-copy"><small>OPTION ${'ABCD'[j]}</small>${esc(o)}</span></button>`).join('')}</div><div id="feedback" class="feedback" role="status" aria-live="polite"></div><form id="typed-form"><label for="typed">Or type your answer</label><div class="row"><input type="text" id="typed" autocomplete="off" placeholder="Answer or option letter" maxlength="120"><button class="button secondary">Submit</button></div></form></section><aside class="card voice-panel"><button id="listen" class="mic" aria-label="Start listening" ${!Speech?'disabled':''}>♩</button><h3>Make your voice heard.</h3><p>Say the answer or its letter.</p><div class="wave" aria-hidden="true">${[10,21,14,30,19,35,15,26,12].map(h=>`<i style="--h:${h}px"></i>`).join('')}</div><p id="speech-message" class="speech-message" role="status">${Speech?'Tap the microphone to answer.':'Voice isn’t available in this browser. Click or type an answer.'}</p><button id="pause" class="button secondary">${autoListen?'Pause auto-listening':'Enable auto-listening'}</button><label for="speech-language">Speech language</label><select id="speech-language">${[['en-US','English (US)'],['en-PH','English (Philippines)'],['en-GB','English (UK)']].map(([code,label])=>`<option value="${code}" ${speechLanguage===code?'selected':''}>${label}</option>`).join('')}</select><div id="speech-suggestions"></div><p class="fine">No audio is stored by GeoVoice.</p></aside></div>`;
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>submitAnswer(Number(b.dataset.answer)));
 $('#typed-form').onsubmit=e=>{e.preventDefault();acceptTranscript($('#typed').value,false);};$('#listen').onclick=()=>{speechRetries=0;startListening();};$('#speech-language').onchange=()=>{stopSpeech();speechLanguage=$('#speech-language').value;try{localStorage.setItem('geovoice-speech-language',speechLanguage);}catch{}speechRetries=0;$('#speech-message').textContent='Speech language updated. Tap the microphone to try it.';};$('#pause').disabled=!Speech;
 $('#pause').onclick=()=>{autoListen=!autoListen;stopSpeech();$('#pause').textContent=autoListen?'Pause auto-listening':'Enable auto-listening';if(autoListen)startListening();else $('#speech-message').textContent='Auto-listening paused. Tap the microphone when ready.';};
 $('#read').disabled=!('speechSynthesis'in window);$('#read').onclick=()=>{stopSpeech();speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(q.prompt+'. '+q.options.map((o,j)=>'ABCD'[j]+', '+o).join('. '));utterance.lang='en-US';const activeRun=run;utterance.onend=()=>{if(autoListen&&view==='quiz'&&!answerLocked&&run===activeRun&&run.answers.length===i)startListening();};speechSynthesis.speak(utterance);};$('#exit').onclick=()=>confirmAction('Head back home?','Your completed quizzes are safe. This unfinished quiz will not be added to your results.','Quit & go home',()=>{run=null;home();});
 $('.question').focus({preventScroll:true});window.scrollTo?.({top:0,behavior:'instant'});if(autoListen)startListening();
}
async function acceptTranscript(text,spoken=true){if(view!=='quiz'||answerLocked)return false;const q=run.questions[run.answers.length],selected=resolveAnswer(text,q.options);if($('#speech-message')&&spoken)$('#speech-message').textContent=`Heard: “${text}”`;if(selected===null){toast('That did not match an option. Say the full answer or A, B, C, or D.');return false;}return await submitAnswer(selected);}
function startListening(){if(!Speech||recognition||view!=='quiz'||answerLocked)return;window.speechSynthesis?.cancel();const currentRun=run,index=run.answers.length;const r=new Speech();recognition=r;r.lang=speechLanguage;r.continuous=false;r.interimResults=true;r.maxAlternatives=5;let retryAllowed=true,handledFinal=false;$('#speech-suggestions').innerHTML='';$('#listen').classList.add('listening');$('#listen').disabled=true;$('#speech-message').textContent='Listening… say your answer.';
 r.onresult=e=>{if(recognition!==r||view!=='quiz'||run!==currentRun||run.answers.length!==index||answerLocked||handledFinal)return;
  const result=e.results[e.resultIndex],text=result?.[0]?.transcript||'';
  if(!result?.isFinal){$('#speech-message').textContent=`Hearing: “${text}”`;const candidate=resolveAnswer(text,run.questions[index].options);$('#speech-suggestions').innerHTML=candidate===null?'':`<button class="button secondary full" id="speech-submit-now">Submit ${'ABCD'[candidate]} now</button>`;if($('#speech-submit-now'))$('#speech-submit-now').onclick=()=>{if(view==='quiz'&&run===currentRun&&run.answers.length===index&&!answerLocked)return submitAnswer(candidate);};return;}
  $('#speech-suggestions').innerHTML='';
  handledFinal=true;const selected=resolveAnswer(text,run.questions[index].options);
  if(selected!==null){return acceptTranscript(text);}
  $('#speech-message').textContent=`Heard: “${text}”. Say the option letter, or try again.`;
  const candidates=[...new Set(Array.from(result).slice(1).map(a=>resolveAnswer(a.transcript,run.questions[index].options)).filter(n=>n!==null))];
  if(candidates.length){retryAllowed=false;$('#speech-suggestions').innerHTML='<p>Did you mean:</p>'+candidates.map(n=>`<button class="button secondary full" data-speech-choice="${n}">${'ABCD'[n]} · ${esc(run.questions[index].options[n])}</button>`).join('');document.querySelectorAll('[data-speech-choice]').forEach(b=>b.onclick=()=>{if(view==='quiz'&&run===currentRun&&run.answers.length===index&&!answerLocked)return submitAnswer(Number(b.dataset.speechChoice));});}
 };
 r.onerror=e=>{if(recognition!==r||view!=='quiz')return;retryAllowed=e.error==='no-speech';const messages={'not-allowed':'Microphone permission was denied. Allow it in your browser settings, or click an answer.','audio-capture':'No working microphone was found.','network':'Speech recognition needs a network connection. Try again, or click an answer.','no-speech':'No speech heard. Tap the microphone to try again.','aborted':'Listening stopped.','service-not-allowed':'Speech recognition is unavailable in this browser. Use the answer buttons.'};$('#speech-message').textContent=messages[e.error]||'Could not recognize speech. Tap the microphone to retry.';};
 r.onspeechend=()=>{if(recognition===r&&!handledFinal&&view==='quiz'){r.stop?.();$('#speech-message').textContent='Checking what you said…';}};
 r.onend=()=>{if(recognition!==r)return;recognition=null;if(view==='quiz'&&run===currentRun&&run.answers.length===index){$('#listen').classList.remove('listening');$('#listen').disabled=answerLocked;
  if(!answerLocked&&autoListen&&retryAllowed&&!$('#speech-suggestions').textContent&&!document.hidden&&speechRetries<3){speechRetries++;speechRetryTimer=setTimeout(()=>{if(view==='quiz'&&run===currentRun&&run.answers.length===index&&!answerLocked&&!document.hidden)startListening();},500);}
  else if(!answerLocked&&!$('#speech-suggestions').textContent){$('#speech-message').textContent+=' Tap the microphone to try again.';}
 }};

 try{r.start();}catch{recognition=null;$('#listen').classList.remove('listening');$('#listen').disabled=false;$('#speech-message').textContent='Could not start listening. Use an answer button or try again.';}
}
async function submitAnswer(selected){
 if(view!=='quiz'||answerLocked||busy||!Number.isInteger(selected)||selected<0||selected>3)return false;
 answerLocked=true;busy=true;stopSpeech();window.speechSynthesis?.cancel();const index=run.answers.length;$('#speech-suggestions').innerHTML='';$('#speech-message').textContent='Answer received. Checking…';$('#feedback').innerHTML='<div class="notice">Checking answer…</div>';
 document.querySelectorAll('[data-answer],#listen,#pause,#read,#typed-form button,#exit').forEach(b=>b.disabled=true);
 try{const response=await api(`/quizzes/${run.id}/answer`,'POST',{index,selected});const {question:q}=response.answer;run.answers.push(response.answer);if(response.next)run.questions[run.answers.length]=response.next.question;run.result=response.result;
 document.querySelectorAll('[data-answer]').forEach(b=>{const n=Number(b.dataset.answer);if(n===q.answer){b.classList.add('correct');b.insertAdjacentHTML('beforeend','<span class="answer-verdict">✓ Correct</span>');}else if(n===selected){b.classList.add('wrong');b.insertAdjacentHTML('beforeend','<span class="answer-verdict">✕ Your answer</span>');}});$('#typed-form').hidden=true;const correct=selected===q.answer;
 $('#feedback').innerHTML=`<div class="notice ${correct?'':'error'}"><strong>${correct?'That’s right!':'A new thing to know.'}</strong><p>${!correct?`The answer is ${esc(q.options[q.answer])}. `:''}${esc(q.explanation)}</p></div><div class="row spaced"><span class="fine" id="advance-label">Continuing in 5 seconds…</span><div><button class="text-button" id="hold">Pause</button><button class="button secondary" id="next">${response.result?'See results':'Next question'} →</button></div></div>`;
 const next=()=>{if(view!=='quiz'||!answerLocked)return;clearTimeout(advanceTimer);if(run.result){const result=run.result;run=null;showResult(result);}else renderQuestion();};$('#next').onclick=next;$('#hold').onclick=()=>{clearTimeout(advanceTimer);$('#advance-label').textContent='Take your time. Continue when ready.';$('#hold').hidden=true;};advanceTimer=setTimeout(next,5000);$('#exit').disabled=false;return true;
 }catch(error){answerLocked=false;$('#feedback').innerHTML='';$('#speech-message').textContent='Could not check your answer. Please retry.';document.querySelectorAll('[data-answer],#typed-form button,#exit').forEach(b=>b.disabled=false);$('#listen').disabled=!Speech;$('#pause').disabled=!Speech;$('#read').disabled=!('speechSynthesis'in window);toast(error.message+' You can retry the same answer.');return false;}finally{busy=false;}
}
function showResult(result,saved=true){cleanup();routeVersion++;view='results';shell('Geography quiz','Your results');main.innerHTML=intro('ANOTHER ADVENTURE COMPLETE',result.percent>=80?'Look at what you know.':'Every answer is a discovery.','Keep your curiosity going. There’s always more of the world to explore.')+`<section class="card"><div class="row"><div><span class="result-medal" aria-hidden="true">✦</span><span class="score-number">${result.percent}<span style="font-size:30px">%</span></span><p class="muted">${result.correct} of ${result.total} questions correct · ${esc(result.category)}</p></div><div><button class="button primary" id="again">Explore again →</button><button class="text-button" id="progress-link">My progress</button></div></div><div class="notice ${saved?'':'error'}">${saved?'This result is saved to your account.':'This result could not be saved. Keep this page open to review your answers.'}</div></section><h2 class="section-title">Your discoveries</h2><section class="card">${result.answers.map((a,i)=>`<article class="review-item"><div class="row"><span class="eyebrow">QUESTION ${i+1}</span><span class="tag ${a.selected===a.question.answer?'':'bad'}">${a.selected===a.question.answer?'Correct':'Keep learning'}</span></div><h3 class="spaced">${esc(a.question.prompt)}</h3><p>Your answer: <strong>${esc(a.question.options[a.selected])}</strong>${a.selected!==a.question.answer?` · Correct answer: <strong>${esc(a.question.options[a.question.answer])}</strong>`:''}</p><p class="muted">${esc(a.question.explanation)}</p></article>`).join('')}</section>`;$('#again').onclick=home;$('#progress-link').onclick=()=>history();}
async function history(page=0){cleanup();view='history';const ticket=++routeVersion;shell('My progress','Learning history');main.innerHTML='<p class="muted" role="status">Loading your progress…</p>';try{const data=await api('/history?page='+page);if(ticket!==routeVersion)return;const {attempts,stats,hasMore}=data;
 main.innerHTML=intro('YOUR EXPLORER LOG','Look how far you’ve come.','Explore your results and revisit what you’ve learned.')+`<div class="stat-grid"><div class="stat"><strong>${stats.quizzes}</strong><span>Quizzes completed</span></div><div class="stat"><strong>${stats.total}</strong><span>Questions explored</span></div><div class="stat"><strong>${stats.total?Math.round(stats.correct/stats.total*100):0}%</strong><span>Overall accuracy</span></div></div><section class="card">${attempts.length?`<h2>Recent quizzes</h2>${attempts.map(a=>`<div class="history-row"><div><strong>${esc(a.category==='All'?'Around the world':a.category)}</strong><p>${new Date(a.date).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})} · ${a.correct}/${a.total} correct</p></div><div class="row"><span class="history-score">${a.percent}%</span><button class="text-button" data-review="${a.id}">Review →</button></div></div>`).join('')}`:'<div class="empty"><h2>Your first quiz is waiting.</h2><p>Finish a quiz to see your results here.</p><button class="button primary" id="first-quiz">Explore a topic →</button></div>'}<div class="row spaced"><button id="history-prev" class="button secondary" ${page===0?'disabled':''}>Previous</button><span class="fine">Page ${page+1}</span><button id="history-next" class="button secondary" ${!hasMore?'disabled':''}>Next</button></div></section>`;
 $('#first-quiz')?.addEventListener('click',home);$('#history-prev').onclick=()=>history(page-1);$('#history-next').onclick=()=>history(page+1);document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>showResult(attempts.find(a=>a.id===b.dataset.review)));
 }catch(error){if(ticket===routeVersion){main.innerHTML=`<div class="notice error">${esc(error.message)}</div><button id="retry-history" class="button secondary spaced">Retry</button>`;$('#retry-history').onclick=()=>history(page);}}
}
function settings(){cleanup();routeVersion++;view='settings';shell('My profile','Account & devices');main.innerHTML=intro('YOUR EXPLORER PROFILE','Make yourself at home.','Update your sign-in details and manage your saved progress.')+`<div class="grid"><section class="card"><h2>${esc(user.name)}</h2><p class="muted">@${esc(user.username)} · Joined ${new Date(user.created).toLocaleDateString()}</p><button id="sign-out" class="button secondary full">Sign out</button><h3 class="section-title">Account security</h3><button id="change-password" class="button secondary full">Change password</button><button id="reenroll-face" class="button secondary full">Update face template</button><button id="replace-recovery" class="button secondary full">Replace recovery code</button><h3 class="section-title">Your data</h3><button id="export" class="button secondary full">Download my quiz history</button><button id="delete-profile" class="button danger full">Delete my account</button></section><section class="card"><h2>Camera & microphone</h2><p>Choose your webcam on the face verification screen. GeoVoice remembers your choice on this device.</p><p>If your camera is unavailable, check your browser’s camera permission and close other apps using the webcam.</p><p>Voice answers use your browser’s speech recognition. If it is unavailable, click or type an answer.</p><h3 class="section-title">Privacy</h3><p>Your account and quiz history are available across devices. Camera images and voice recordings are not stored by GeoVoice.</p><button id="privacy-settings" class="text-button">Read the privacy notice</button></section></div>`;
 $('#sign-out').onclick=async()=>{if(busy)return;busy=true;try{await api('/auth/logout','POST',{});user=null;clearSession();auth();}catch(error){if(error.status===401){user=null;clearSession();auth();}else errorMessage(error);}finally{busy=false;}};
 $('#privacy-settings').onclick=privacy;
 $('#change-password').onclick=()=>passwordDialog('Change your password',true,async(currentPassword,newPassword)=>{const response=await api('/account/password','POST',{currentPassword,newPassword});user=response.user;toast('Password updated. Other sessions have been signed out.');});
 $('#reenroll-face').onclick=()=>passwordDialog('Update your face template',false,async password=>{draft={password};camera('reenroll');},'Continue to camera');
 $('#replace-recovery').onclick=()=>passwordDialog('Replace your recovery code',false,async password=>{const response=await api('/account/recovery-code','POST',{password});recoveryDialog(response.recoveryCode);},'Replace code');
 $('#delete-profile').onclick=()=>passwordDialog('Delete your account?',false,async password=>{await api('/account','DELETE',{password});user=null;clearSession();auth();toast('Your account and saved results have been deleted.');},'Delete account','This permanently removes your face template and quiz history from the active database.');
 $('#export').onclick=async()=>{if(busy)return;busy=true;$('#export').disabled=true;try{const data=await api('/account/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='geovoice-history.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){errorMessage(error);}finally{busy=false;if($('#export'))$('#export').disabled=false;}};
}
function passwordDialog(title,withNew,action,label='Save changes',description='Enter your current password to continue.'){
 const dialog=document.createElement('dialog');dialog.setAttribute('aria-labelledby','password-title');dialog.innerHTML=`<h2 id="password-title">${esc(title)}</h2><p>${esc(description)}</p><form id="password-form">${passwordInput('current-password','Current password')}${withNew?passwordInput('new-password','New password','new-password')+passwordInput('confirm-new','Confirm new password','new-password'):''}<div class="notice error spaced" id="password-error" role="alert" hidden></div><div class="row spaced"><button class="button secondary" type="button" id="password-cancel">Cancel</button><button class="button ${label==='Delete account'?'danger':'primary'}" id="password-save">${esc(label)}</button></div></form>`;document.body.append(dialog);const close=()=>{dialog.close();dialog.remove();};$('#password-cancel').onclick=close;dialog.oncancel=e=>{e.preventDefault();if(!busy)close();};$('#password-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const password=$('#current-password').value,newPassword=$('#new-password')?.value;if(withNew&&newPassword!==$('#confirm-new').value){$('#password-error').hidden=false;$('#password-error').textContent='The new passwords do not match.';return;}busy=true;$('#password-save').disabled=true;$('#password-cancel').disabled=true;try{await action(password,newPassword);close();}catch(error){$('#password-error').hidden=false;$('#password-error').textContent=error.message;}finally{busy=false;if($('#password-save')){$('#password-save').disabled=false;$('#password-cancel').disabled=false;}}};dialog.showModal();
}
function privacy(){const dialog=document.createElement('dialog');dialog.className='privacy-dialog';dialog.setAttribute('aria-labelledby','privacy-title');dialog.innerHTML=`<h2 id="privacy-title">Your privacy</h2><p>GeoVoice stores your username, display name, password hash, encrypted face template, and quiz results. These records let you sign in and keep your progress across devices.</p><p>Camera images are processed on your device and are not uploaded. Only numerical face templates are sent to the server. Your password protects account access; face recognition can make mistakes and does not prove that a person is physically present.</p><p>Your browser’s speech service may process audio when you use voice answers. GeoVoice does not save camera images or audio.</p><p>Account data is kept until you delete your account. Unverified registrations expire after 24 hours. Account deletion removes active records; backups may retain copies until their retention period ends.</p><p>You can download quiz history, update your face template, or delete your account under My profile. To recover an account you need its recovery code.</p><p>Operator: ${esc(config.operator||'GeoVoice')}${config.privacyContact?`<br>Privacy contact: <a href="mailto:${esc(config.privacyContact)}">${esc(config.privacyContact)}</a>`:''}</p><button id="privacy-close" class="button primary full">Close</button>`;document.body.append(dialog);const close=()=>{dialog.close();dialog.remove();};$('#privacy-close').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};dialog.showModal();}
function confirmAction(title,body,label,action){stopSpeech();window.speechSynthesis?.cancel();clearTimeout(advanceTimer);const dialog=document.createElement('dialog');dialog.setAttribute('aria-label',title);dialog.innerHTML=`<h2>${esc(title)}</h2><p>${esc(body)}</p><div class="row spaced"><button class="button secondary" id="dialog-cancel">Cancel</button><button class="button danger" id="dialog-confirm">${esc(label)}</button></div>`;document.body.append(dialog);const close=()=>{dialog.close();dialog.remove();if(view==='quiz'&&answerLocked&&$('#advance-label'))$('#advance-label').textContent='Paused. Continue when ready.';};$('#dialog-cancel').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};$('#dialog-confirm').onclick=async()=>{try{await action();close();}catch(error){close();errorMessage(error);}};dialog.showModal();}
function navigate(destination){if(busy){toast('Please wait for the current operation to finish.');return;}if(!user){toast('Complete sign-in to access your account.');return;}const action=()=>{run=null;({quiz:home,history:()=>history(),settings}[destination]||home)();};if(view==='quiz')confirmAction('Leave this quiz?','Your unfinished quiz will not be included in your results.','Leave quiz',action);else action();}
for(const button of document.querySelectorAll('[data-nav]'))button.onclick=()=>navigate(button.dataset.nav);$('#account').onclick=()=>navigate('settings');$('#privacy-link').onclick=privacy;
window.addEventListener('pagehide',()=>{draft=null;cleanup();});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopSpeech();if(view==='camera'){stopCamera();if($('#capture'))$('#capture').disabled=true;if($('#camera-status'))$('#camera-status').textContent='Camera off';cameraMessage('Camera paused. Enable it again when you return.');}if(view==='quiz'&&answerLocked){clearTimeout(advanceTimer);if($('#advance-label'))$('#advance-label').textContent='Paused while you were away. Continue when ready.';}}});
async function initialize(){main.innerHTML='<p role="status" class="muted">Connecting to GeoVoice…</p>';try{config=await api('/config');const response=await api('/session');if(response.stage==='full'){user=response.user;home();}else if(response.stage==='face')camera('login');else auth();}catch(error){main.innerHTML=intro('GEOVOICE','Unable to connect.',error.message)+'<button class="button primary" id="reload">Try again</button>';$('#reload').onclick=initialize;}}
await initialize();
if(document.modelContext?.registerTool){const life=new AbortController();try{await document.modelContext.registerTool({name:'answer_geography_question',title:'Answer geography question',description:'Submit an answer to the active signed-in quiz; scores are validated by the server.',inputSchema:{type:'object',properties:{option:{type:'string',enum:['A','B','C','D']}},required:['option'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!input||Object.keys(input).length!==1||!['A','B','C','D'].includes(input.option))throw new Error('Provide one option: A, B, C, or D.');if(!user||view!=='quiz'||answerLocked||busy)throw new Error('No signed-in quiz question is awaiting an answer.');const ok=await submitAnswer('ABCD'.indexOf(input.option));if(!ok)throw new Error('Answer could not be submitted.');return {answered:run.answers.length,correct:score(run.answers).correct};}},{signal:life.signal});window.addEventListener('pagehide',()=>life.abort(),{once:true});}catch(error){console.info('Optional agent controls unavailable.');}}
